                self.assertEqual(round(value, 6), value)


class GroupByValidationTest(unittest.TestCase):
    def test_bad_group_by(self):
        records = [{"a": 1}]
        for raw in (1, "x", {}, [1], ["/a", "/a"], ["/b"], ["/a"], ["/a/x"], ["bad"]):
